use vstd::prelude::*;

verus! {

fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
    ensures
        // the result has the same length as the input
        b.len() == a.len(),
        // and each element is copied exactly
        forall|i: usize| i < a.len() ==>
            b[i] == a[i],
{
    let mut b = Vec::with_capacity(a.len());
    for &elem in a.iter()
        invariant
            // we never push more than a.len() elements
            b.len() <= a.len(),
            // and at each point, b[..] is a prefix of a[..]
            forall|i: usize| i < b.len() ==>
                b[i] == a[i],
        decreases
            // measure is how many elements remain to copy
            a.len() - b.len(),
    {
        b.push(elem);
    }
    b
}

} // end of verus! block

